#!/bin/bash
sed -i 's/NavHost(/val rateLimitCountdown by com.example.ai.ApiRateLimitManager.rateLimitCountdown.collectAsState(initial = 0)\n\n    androidx.compose.foundation.layout.Box(modifier = modifier.androidx.compose.foundation.layout.fillMaxSize()) {\n    NavHost(/g' app/src/main/java/com/example/ui/ToonApp.kt
sed -i 's/        modifier = modifier/        modifier = androidx.compose.foundation.layout.Modifier.fillMaxSize()/g' app/src/main/java/com/example/ui/ToonApp.kt
sed -i 's/    }$/\n        androidx.compose.animation.AnimatedVisibility(\n            visible = rateLimitCountdown > 0,\n            modifier = androidx.compose.ui.Modifier.align(androidx.compose.ui.Alignment.TopCenter).androidx.compose.foundation.layout.padding(top = 32.dp),\n            enter = androidx.compose.animation.slideInVertically { -it } + androidx.compose.animation.fadeIn(),\n            exit = androidx.compose.animation.slideOutVertically { -it } + androidx.compose.animation.fadeOut()\n        ) {\n            androidx.compose.material3.Surface(\n                color = androidx.compose.material3.MaterialTheme.colorScheme.errorContainer,\n                contentColor = androidx.compose.material3.MaterialTheme.colorScheme.onErrorContainer,\n                shadowElevation = 8.androidx.compose.ui.unit.dp,\n                shape = androidx.compose.foundation.shape.RoundedCornerShape(8.androidx.compose.ui.unit.dp),\n            ) {\n                androidx.compose.material3.Text(\n                    text = "Limite d'\''API atteinte. Revenez dans $rateLimitCountdown secondes.",\n                    modifier = androidx.compose.ui.Modifier.androidx.compose.foundation.layout.padding(16.androidx.compose.ui.unit.dp),\n                    style = androidx.compose.material3.MaterialTheme.typography.bodyLarge\n                )\n            }\n        }\n    }\n}/g' app/src/main/java/com/example/ui/ToonApp.kt
